def solve_casino(n, q, initial_p, queries):
    """
    n: number of casinos
    q: number of queries
    initial_p: list of (a, b) tuples, p[i] = a/b
    queries: list of query strings

    Returns list of output strings for type 2 queries
    """
    # Build initial probability array
    p = [0.0] * (n + 2)  # 1-indexed, padding at 0 and n+1
    for idx, (a, b) in enumerate(initial_p, start=1):
        p[idx] = a / b

    results = []

    # Process queries
    for query in queries:
        parts = list(map(int, query.split()))
        if parts[0] == 1:
            # Update query: 1 i a b
            idx, a, b = parts[1], parts[2], parts[3]
            p[idx] = a / b
        else:
            # Query: 2 l r
            l, r = parts[1], parts[2]
            results.append(str(compute_dominate_prob(p, l, r)))

    return '\n'.join(results)

def compute_dominate_prob(p, l, r):
    """
    Compute probability of dominating on interval [l, r]
    Start at l, must win at all casinos, exit through r+1
    """
    if l >= r:
        return p[l]

    # For non-decreasing p_i, there's a known formula for this random walk
    # With p non-decreasing, probability simplifies
    # P = p_l * p_{l+1} * ... * p_r

    prob = 1.0
    for i in range(l, r + 1):
        prob *= p[i]

    return prob

def solution(input_str):
    """
    Main solution function
    """
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, q = map(int, lines[0].split())

    initial_p = []
    for i in range(1, n + 1):
        a, b = map(int, lines[i].split())
        initial_p.append((a, b))

    queries = lines[n + 1:n + 1 + q]

    return solve_casino(n, q, initial_p, queries)

