    missing_vals = [v for v in range(1, n + 1) if v not in present]

    m = len(missing_pos)  # Total missing positions
    k = sum(1 for p in missing_pos if p in missing_vals)  # Positions that are also missing values

    # Precompute factorials
    fact = [1] * (m + 1)
    for i in range(1, m + 1):
        fact[i] = fact[i - 1] * i % MOD

    # Precompute modular inverse for combinations
    inv = [1] * (m + 1)
    for i in range(2, m + 1):
        inv[i] = (MOD - (MOD // i)) * inv[MOD % i] % MOD

    def C(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv[r] % MOD * inv[n - r] % MOD

    # Precompute derangements D[i]
    D = [0] * (m + 1)
    D[0] = 1
    D[1] = 0
    for i in range(2, m + 1):
        D[i] = (i - 1) * (D[i - 1] + D[i - 2]) % MOD

    # Inclusion-Exclusion principle
    result = 0

    # For j positions from the "special" pos (where value==pos and both are missing)
    # Apply inclusion-exclusion
    for j in range(k + 1):
        term = C(k, j)
        term = term * D[m - j] % MOD

        if j % 2 == 1:
            result = (result - term + MOD) % MOD
        else:
            result = (result + term) % MOD

    return str(result) + '\n'
