```python
def solution(input_data):
    import math
    from collections import defaultdict

    lines = input_data.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())

    adj = defaultdict(list)
    for line in lines[1:]:
        if line.strip():
            u, v = map(int, line.split())
            adj[u].append(v)
            adj[v].append(u)

    # Calculate ceil(sqrt(n))
    sq = int(math.sqrt(n))
    if sq * sq == n:
        target = sq
    else:
        target = sq + 1

    parent = {}
    depth = {}
    found_cycle = None

    def dfs(u, p, d):
        nonlocal found_cycle
        parent[u] = p
        depth[u] = d

        for v in adj[u]:
            if v == p:
                continue
            if v in depth:
                # Back edge - potential cycle
                # Cycle length = depth[u] - depth[v] + 1
                if depth[u] - depth[v] + 1 >= target:
                    # Build the cycle by backtracking through parent pointers
                    cycle_path = []
                    curr = u
                    while curr != v:
                        cycle_path.append(curr)
                        curr = parent[curr]
                    cycle_path.append(v)
                    found_cycle = sorted(cycle_path)
                    return
            else:
                dfs(v, u, d + 1)
                if found_cycle is not None:
                    return

    # Start DFS from vertex 1
    dfs(1, 0, 0)

    if found_cycle is not None:
        # Output the cycle
        return f"2\n{len(found_cycle)}\n{' '.join(map(str, found_cycle))}\n"

    # No cycle found, construct independent set using BFS levels
    # In BFS, vertices at the same level are never directly connected in the BFS tree
    # (cross edges don't exist in BFS tree in the same way)

    visited = {1}
    bfs_order = [1]
    bfs_depth = {1: 0}

    idx = 0
    while idx < len(bfs_order):
        u = bfs_order[idx]
        idx += 1
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                bfs_order.append(v)
                bfs_depth[v] = bfs_depth[u] + 1

    # Take all vertices at even BFS depths
    indep_set = []
    for u in bfs_order:
        if bfs_depth[u] % 2 == 0:
            indep_set.append(u)

    # Output the independent set
    return f"1\n{len(indep_set)}\n{' '.join(map(str, indep_set))}\n"
