        for i in range(n):
            matrix.append(list(map(int, lines[idx].split())))
            idx += 1

        ops = lines[idx]
        idx += 1

        for op in ops:
            if op == 'R':
                # Shift columns right
                for i in range(n):
                    matrix[i] = [matrix[i][j-1] if j > 0 else matrix[i][n-1] for j in range(n)]
            elif op == 'L':
                # Shift columns left
                for i in range(n):
                    matrix[i] = [matrix[i][j+1] if j+1 < n else matrix[i][0] for j in range(n)]
            elif op == 'D':
                # Shift rows down
                new_matrix = matrix[-1] + matrix[:-1]
                matrix = new_matrix
            elif op == 'U':
                # Shift rows up
                new_matrix = matrix[1:] + [matrix[0]]
                matrix = new_matrix
            elif op == 'I':
                # Inverse each row
                for i in range(n):
                    row = matrix[i]
                    pos = [0] * n
                    for val in row:
                        pos[val-1] = i + 1
                    matrix[i] = [pos[val-1] for val in row]
            elif op == 'C':
                # Inverse each column
                # First transpose
                transpose = [[matrix[i][j] for i in range(n)] for j in range(n)]
                # Compute inverse of each column
                for j in range(n):
                    col = transpose[j]
                    pos = [0] * n
                    for i in range(n):
                        pos[col[i]-1] = i + 1
                    transpose[j] = [pos[val-1] for val in col]
                # Transpose back
                matrix = [[transpose[j][i] for j in range(n)] for i in range(n)]

        output.append('\n'.join([' '.join(map(str, row).rstrip()) for row in matrix]))

    return '\n'.join(output)
