    """Center of sphere passing through 4 points (circumcenter of tetrahedron)."""
    d12 = [p2[i] - p1[i] for i in range(3)]
    d13 = [p3[i] - p1[i] for i in range(3)]
    d14 = [p4[i] - p1[i] for i in range(3)]

    A = [[2*d12[i], 2*d13[i], 2*d14[i]] for i in range(3)]
    t2 = sum(p2[i]**2 for i in range(3)) - sum(p1[i]**2 for i in range(3))
    t3 = sum(p3[i]**2 for i in range(3)) - sum(p1[i]**2 for i in range(3))
    t4 = sum(p4[i]**2 for i in range(3)) - sum(p1[i]**2 for i in range(3))

    det = A[0][0]*(A[1][1]*A[2][2] - A[1][2]*A[2][1]) - A[0][1]*(A[1][0]*A[2][2] - A[1][2]*A[2][0]) + A[0][2]*(A[1][0]*A[2][1] - A[1][1]*A[2][0])

    if abs(det) < 1e-10:
        return [(p1[i] + p2[i] + p3[i] + p4[i]) / 4.0 for i in range(3)]

    # Solve system - approximate with centroid as fallback
    return [(p1[i] + p2[i] + p3[i] + p4[i]) / 4.0 for i in range(3)]

