    def __len__(self):
        return 0

    def __iter__(self):
        return iter([])


def nCr(n, r):
    """Calculate combinations C(n,r) using log-gamma to handle large numbers."""
    if r < 0 or r > n:
        return 0
    return math.lgamma(n + 1) - math.lgamma(r + 1) - math.lgamma(n - r + 1)


def solution(input_str):
