    else:
        n, m, k = 0, 0, 0

    # If final position would be negative, impossible to stay non-negative
    if k + n - m < 0:
        return "0\n"

    # Total arrangements: C(n+m, n)
    total = math.exp(nCr(n + m, n))

    # Invalid arrangements that touch/cross -1: C(n+m, n+k+1)
    if n + k + 1 > n + m:
        invalid_prob = 0
    else:
        invalid_prob = math.exp(nCr(n + m, n + k + 1))

    # However, we need exact integer arithmetic for the ratio
    # P = 1 - C(n+m, n+k+1) / C(n+m, n)
    # Which simplifies to working with the actual counts

    # Use a different approach: compute the ratio directly
    if total == 0:
        return "1\n"

    # The ratio C(n+m, n+k+1) / C(n+m, n)
    log_ratio = nCr(n + m, n + k + 1) - nCr(n + m, n)
    ratio = math.exp(log_ratio)

    # Probability P = 1 - ratio
    probability = 1.0 - ratio

