    # Simpler: compute valid/total as ratio of combinations
    if n + k + 1 > n + m:
        probability = 1.0
    else:
        # C(n+m, n+k+1) / C(n+m, n) = [n! m!] / [(n+k+1)! (m-k-1)!]
        # This equals product for i from 1 to k+1 of (m+i)/(n-k) approximately

        # Use the formula: P = (n - m + 1)/(n + 1) for k=0, generalize this
        probability = (n + k + 1 - m) / (n + m + k + 1) if (n + k + 1 - m) > 0 else (n + 1) / (n + m + k + 1)

    # Actually, the simplest working formula:
    # P = (C(n+m,n) - C(n+m,n+k+1)) / C(n+m,n)
    # For large values, this equals 1 - C(n+m, m-k-1)/C(n+m, m)

    if m <= k:
        probability = 1.0
    elif k + n - m < 0:
        probability = 0.0
    else:
        # General formula: (n + 1 - m + k - 1) / (n + 1 + k) 
        # Simplifying: (n + k + 2 - m) / (n + k + 2)
        probability = (n - m + k + 2) / (n + k + 2)

    return f"{probability:.12f}\n"
