import math

def nCr_exact(n, r):
    """Calculate C(n,r) exactly using Python's big integers."""
    if r < 0 or r > n:
        return 0
    r = min(r, n - r)
    result = 1
    for i in range(r):
        result = result * (n - i) // (i + 1)
    return result

def solution(input_str):
    n, m, k = map(int, input_str.strip().split())

    if k + n - m < 0:
        return "0\n"

    if n + m == 0:
        return "1\n"

    if m <= k:
        return "1\n"

    total = nCr_exact(n + m, n)
    if n + k + 1 > n + m:
        valid = total
    else:
        invalid = nCr_exact(n + m, n + k + 1)
        valid = total - invalid

    probability = valid / total
    return f"{probability:.12f}\n"
