Looking at this problem, I need to understand the constraints:

1. If x ∈ A, then a-x must also be in A (if a-x exists in input)
2. If x ∈ B, then b-x must also be in B (if b-x exists in input)

This creates dependency groups: elements connected by complement relationships must be in the same set. I'll use a union-find approach to group these elements, then verify and assign each group consistently.

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    if n == 0:
        return "YES\n"

    # Map value to its index
    pos = {v: i for i, v in enumerate(p)}

    # Union-Find to group elements that must be together
    parent = list(range(n))
    def find(i):
        if parent[i] != i:
            parent[i] = find(parent[i])
        return parent[i]
    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    # Build groups: x and a-x must be together, x and b-x must be together
    for i in range(n):
        x = p[i]
        if (a - x) in pos:
            union(i, pos[a - x])
        if (b - x) in pos:
            union(i, pos[b - x])

    # Find all components and what they can support
    components = {}
    for i in range(n):
        root = find(i)
        if root not in components:
            components[root] = []
        components[root].append(i)

    # Track which components can go to A or B
    can_a = {}  # component root -> True = can be in A
    can_b = {}  # component root -> True = can be in B

    for root, indices in components.items():
        can_a[root] = True
        can_b[root] = True

    # Validate and update constraints
    for i in range(n):
        x = p[i]
        root = find(i)

        # Constraint: if a-x exists, both x and a-x must be in same set
        if (a - x) in pos:
            j = pos[a - x]
            other_root = find(j)
            # Must be same component (should be by construction)
            if root != other_root:
                return "NO"

        # If a-x exists, component must be able to include it
        if (a - x) in pos:
            # If component can't be in A, check if it can be in B
            if not can_a[root]:
                can_b[root] = False  # Invalid

        # Similarly for b-x
        if (b - x) in pos:
            j = pos[b - x]
            other_root = find(j)
            if root != other_root:
                return "NO"
            if not can_b[root]:
                can_a[root] = False  # Invalid

    # Final check: each component must support at least one set
    for root in components:
        if not can_a[root] and not can_b[root]:
            return "NO"

    # Build the solution
    result = [0] * n
    for i in range(n):
        x = p[i]
        root = find(i)
        # Assign to 0 (A) if possible, otherwise 1 (B)
        if can_a[root]:
            result[i] = 0
        else:
            result[i] = 1

    return "YES\n" + " ".join(map(str, result)) + "\n"
